def what(mv):
    nm = rename.get(mv, mv)
    if mv in HAND: return HAND[mv]
    if nm in HAND: return HAND[nm]
    for w, t in TYPE_WORDS:
        if w in mv: return t + ' 계열'
    return '?'
draft = tsv('NDS_종_초안.tsv')
sp_rows = tsv('NDS_필살기.tsv')
specials = {}
dpath = os.path.join(H, 'design.json')
if os.path.exists(dpath):
    for s in json.load(open(dpath, encoding='utf-8')).get('specials', []): specials.setdefault(s['owner'], []).append((1, s['name'], '설계'))
rookies = {r['이름'] for r in draft if r['단계'] in ('성장기', '유년기Ⅱ', '유년기', '유년기Ⅰ')}
has_dub = {r['이름'].strip() for r in sp_rows if (r.get('출처') or '').strip() == '더빙'}
for r in sp_rows:
    o, nm = r['이름'].strip(), r['기술'].strip()
    if not o or not nm: continue
    order = int(r['차례']) if r.get('차례', '').strip().isdigit() else 1
    src = (r.get('출처') or '').strip()
    if o in has_dub: order = 1 if src == '더빙' else 2          # 더빙(만화) 이름이 첫 필살기(hg2 와 같은 규칙)
    if any(x[2] == '설계' for x in specials.get(o, [])) and order == 1: order = 2
    if order == 2 and o in rookies: continue                      # 성장기는 2번 필살기 없음(hg2 와 같음)
    specials.setdefault(o, []).append((order, nm, src))
STAGE_LV = {'유년기Ⅱ': 10, '유년기': 8, '성장기': 12, '성숙기': 22, '아머체': 24, '완전체': 34, '궁극체': 46}   # hg2 와 같게
L = ['# 기술표 — 디지몬마다 레벨별 기술 (표에서 자동 생성, %s)' % __import__('datetime').date.today(), '',
     '> 읽는 법: 「본뜸」 = 능력치·기술을 가져온 포켓몬(hg2 가 그 포켓몬의 자료를 바탕으로 씀). 「디지골드」 = 디지골드가 이미 넣어 둔 디지몬(기술도 디지골드 것). 기술 이름은 게임 안 이름(디지몬식으로 바꾼 것은 그 이름).',
     '> 「무엇」 = 타입과 공격/특수/보조 — 간단히 짐작한 것(? 는 모름). 필살기 = 만화·도감 이름, 그 단계 레벨에 배움(첫 필살기 Lv = 성장기 12 · 성숙기 22 · 아머체 24 · 완전체 34 · 궁극체 46, 둘째 +8). 기술 칸이 모자라면 뒤쪽 종의 둘째 필살기는 못 들어감.',
     '> 고칠 때: NDS_종_초안.tsv 「레벨 기술」 칸(Lv:기술 띄어쓰기) · 이름은 NDS_기술이름.tsv · 필살기는 NDS_필살기.tsv.', '']
rows_tsv = ['이름\t단계\t타입\t본뜸\tLv\t기술\t무엇\t필살기']
for r in draft:
    nm, grade, typ = r['이름'], r['단계'], r['타입']; memo = r.get('메모', '')
    m = re.search(r'「(.+?)」 본뜸', memo); m2 = re.search(r'디지골드 「(.+?)」 그대로', memo)
    base = ('포켓몬 ' + m.group(1)) if m else ('디지골드 ' + m2.group(1) + '(원래 ' + (re.search(r'디지골드 칸: (\S+)', memo).group(1) if re.search(r'디지골드 칸: (\S+)', memo) else '?') + ' 칸)') if m2 else '-'
    moves = []
    for tok in (r.get('레벨 기술') or '').split():
        if ':' not in tok: continue
        lv, mv = tok.split(':', 1); moves.append((int(lv) if lv.isdigit() else 0, mv))
    sp = sorted(specials.get(nm, []))
    sp_txt = ' / '.join('%s(Lv%d, %s)' % (n_, STAGE_LV.get(grade, 20) + (8 if o_ == 2 else 0), s_) for o_, n_, s_ in sp) or '-'
    L += ['## %s (%s · %s) — 본뜸: %s' % (nm, grade, typ, base), '', '필살기: ' + sp_txt, '', '| Lv | 기술 | 무엇 |', '|---|---|---|']
    for lv, mv in sorted(moves):
        L.append('| %d | %s | %s |' % (lv, rename.get(mv, mv), what(mv)))
        rows_tsv.append('\t'.join([nm, grade, typ, base, str(lv), rename.get(mv, mv), what(mv), sp_txt]))
    L.append('')
open(os.path.join(P, '기술표.md'), 'w', encoding='utf-8').write('\n'.join(L) + '\n')
open(os.path.join(P, '기술표.tsv'), 'w', encoding='utf-8', newline='\n').write('\n'.join(rows_tsv) + '\n')
unk = sorted({mv for r in draft for tok in (r.get('레벨 기술') or '').split() if ':' in tok for mv in [tok.split(':', 1)[1]] if what(mv) == '?'})
print('→ 기술표.md / 기술표.tsv (%d종, 「무엇」 모름 %d개: %s)' % (len(draft), len(unk), ' '.join(unk[:40])))
